const cycleId = msg._evopt_cycle;
if (!cycleId) return null;
const key = `evopt_cycle_${cycleId}`;
let cycle = flow.get(key);
if (!cycle) return null;

if (!msg._evopt_timeout) {
    const entity = msg._evopt_entity || msg.entity_id;
    if (entity) {
        cycle.states[entity] = {
            state: msg.payload,
            attributes: (msg.data && msg.data.attributes) ? msg.data.attributes : {}
        };
        cycle.received += 1;
        flow.set(key, cycle);
        if (cycle.received < cycle.expected) return null;
    }
}

flow.set(key, null);
return {
    payload: cycle.states,
    _evopt_cycle: cycleId,
    _evopt_received: cycle.received,
    _evopt_expected: cycle.expected,
    _evopt_timed_out: !!msg._evopt_timeout
};

// EV Charge Optimizer v0.4 - price planner + production executor
// Calculates cheapest non-contiguous 15-minute charge plan.
// The separate executor node controls Tesla Fleet only when Mode = Production.

const S = msg.payload || {};
const now = new Date();
const priceSources = flow.get('evopt_price_sources') || {};

function raw(entity) { return S[entity] || null; }
function state(entity) {
    const x = raw(entity);
    if (!x) return null;
    const s = String(x.state ?? '').trim();
    if (!s || ['unknown','unavailable','none','null'].includes(s.toLowerCase())) return null;
    return s;
}
function num(entity) {
    const s = state(entity);
    if (s === null) return null;
    const n = Number(String(s).replace(',','.'));
    return Number.isFinite(n) ? n : null;
}
function bool(entity) {
    const s = state(entity);
    if (s === null) return null;
    const v = s.toLowerCase();
    if (['on','true','yes','connected'].includes(v)) return true;
    if (['off','false','no','disconnected'].includes(v)) return false;
    return null;
}
function firstNumber(list) {
    for (const e of list) { const n=num(e); if (n!==null) return {value:n,entity:e}; }
    return {value:null,entity:null};
}
function firstState(list) {
    for (const e of list) { const s=state(e); if (s!==null) return {value:s,entity:e}; }
    return {value:null,entity:null};
}
function firstBool(list) {
    for (const e of list) { const b=bool(e); if (b!==null) return {value:b,entity:e}; }
    return {value:null,entity:null};
}
function normalizeLocation(s) {
    return String(s||'').trim().toLowerCase().replace(/_/g,' ').replace(/\s+/g,' ');
}
function controlSite(location) {
    const l=normalizeLocation(location);
    if (l==='home') return 'anemonevej';
    if (['i.a. møllersvej','i.a møllersvej','i.a. mollersvej','i.a mollersvej'].includes(l)) return 'ia_moellersvej';
    return 'none';
}
function estimationSite(location) {
    return controlSite(location)==='ia_moellersvej' ? 'ia_moellersvej' : 'anemonevej';
}
function fmtLocal(d) {
    const pad=n=>String(n).padStart(2,'0');
    return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}
function parseHaDateTime(v) {
    if (!v) return null;
    const d=new Date(String(v).replace(' ','T'));
    return Number.isFinite(d.getTime()) ? d : null;
}
function nextClock(hour,minute,base=now) {
    const d=new Date(base);
    d.setHours(hour,minute,0,0);
    if (d<=base) d.setDate(d.getDate()+1);
    return d;
}
function addHours(base,h) { return new Date(base.getTime()+h*3600000); }
function bandFor(soc,target) {
    if (soc===null || target===null) return 'unknown';
    if (soc>=target) return 'target_reached';
    if (soc<5) return 'below_5';
    if (soc<10) return '5_to_10';
    if (soc<50) return '10_to_50';
    return 'above_50';
}
function safeText(v,max=250) {
    return String(v??'').replace(/[\r\n]+/g,' ').replace(/"/g,"'").slice(0,max);
}
function setNumber(entity_id,value) {
    return {ha_action:'input_number.set_value',entity_id,value:Number(value)};
}
function setText(entity_id,value) {
    return {ha_action:'input_text.set_value',entity_id,value:safeText(value)};
}
function setDateTime(entity_id,value) {
    return {ha_action:'input_datetime.set_datetime',entity_id,value:fmtLocal(value)};
}
function setBool(entity_id,value) {
    return {ha_action:value?'input_boolean.turn_on':'input_boolean.turn_off',entity_id};
}
function minDate(a,b) {
    if (!a) return b;
    if (!b) return a;
    return a<b?a:b;
}
function siteKw(amps) {
    return amps && amps>0 ? 3*230*amps/1000 : null;
}
function iso(d) { return d ? d.toISOString() : ''; }
function round2(n) { return Math.round((n+Number.EPSILON)*100)/100; }

function plannedSlotsText(plan) {
    const slots=(plan?.selected||[])
        .map(x=>({start:new Date(x.start),end:new Date(x.end)}))
        .filter(x=>Number.isFinite(x.start.getTime())&&Number.isFinite(x.end.getTime())&&x.end>x.start)
        .sort((a,b)=>a.start-b.start);

    if (!slots.length) return 'none';

    // Merge adjacent selected 15-minute slots into human-friendly ranges.
    const merged=[];
    for (const s of slots) {
        const prev=merged[merged.length-1];
        if (prev && Math.abs(s.start.getTime()-prev.end.getTime())<=2000) {
            prev.end=s.end;
        } else {
            merged.push({start:new Date(s.start),end:new Date(s.end)});
        }
    }

    const pad=n=>String(n).padStart(2,'0');
    const today=new Date();
    const sameDay=(a,b)=>a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate();
    const fmtTime=d=>`${pad(d.getHours())}:${pad(d.getMinutes())}`;
    const fmtDate=d=>`${pad(d.getDate())}/${pad(d.getMonth()+1)}`;

    const pieces=merged.map(r=>{
        if (sameDay(r.start,today) && sameDay(r.end,r.start)) {
            return `${fmtTime(r.start)}-${fmtTime(r.end)}`;
        }
        if (sameDay(r.start,r.end)) {
            return `${fmtDate(r.start)} ${fmtTime(r.start)}-${fmtTime(r.end)}`;
        }
        return `${fmtDate(r.start)} ${fmtTime(r.start)}-${fmtDate(r.end)} ${fmtTime(r.end)}`;
    });

    const full=pieces.join(', ');
    return full.length<=250 ? full : full.slice(0,247)+'...';
}

const mode=state('input_select.ev_charge_optimizer_mode') || 'Log only';
const configInitialized=bool('input_boolean.ev_charge_optimizer_config_initialized')===true;
const marginMin=configInitialized ? (num('input_number.ev_charge_long_trip_safety_margin_minutes') ?? 15) : 15;

// Price differences inside this tolerance are treated as equal.
// HA stores the value in øre/kWh; real_energy prices are DKK/kWh.
const priceToleranceInitialized=bool('input_boolean.ev_charge_price_tolerance_initialized')===true;
const priceEqualToleranceOre=priceToleranceInitialized
    ? (num('input_number.ev_charge_price_equal_tolerance_ore_per_kwh') ?? 0.5)
    : 0.5;
const priceEqualToleranceDkk=Math.max(0,priceEqualToleranceOre)/100;

const sites={
    anemonevej:{
        enabled:configInitialized ? (bool('input_boolean.ev_site_anemonevej_enabled')!==false) : true,
        amps:configInitialized ? num('input_number.ev_site_anemonevej_grid_limit_amps') : 26,
        priceSource:configInitialized ? (state('input_text.ev_site_anemonevej_price_source')||'real_energy') : 'real_energy'
    },
    ia_moellersvej:{
        enabled:configInitialized ? (bool('input_boolean.ev_site_ia_moellersvej_enabled')!==false) : true,
        amps:configInitialized ? num('input_number.ev_site_ia_moellersvej_grid_limit_amps') : 0,
        priceSource:configInitialized ? (state('input_text.ev_site_ia_moellersvej_price_source')||'real_energy') : 'real_energy'
    }
};

const cars={
    blue_flux:{
        name:'Blue Flux',
        soc:['sensor.blue_flux_broker_battery_level','sensor.blue_flux_battery_level'],
        target:['sensor.blue_flux_broker_charge_limit_actual','number.blue_flux_charge_limit'],
        location:['sensor.blue_flux_broker_location','device_tracker.blue_flux_location'],
        connected:['binary_sensor.blue_flux_broker_charge_cable_connected','binary_sensor.blue_flux_charge_cable'],
        charging:['sensor.blue_flux_broker_charger_state','sensor.blue_flux_charging'],
        capacity:'input_number.blue_flux_optimizer_battery_capacity_kwh',
        maxAc:'input_number.blue_flux_optimizer_max_ac_kw',
        defaultCapacity:75,
        defaultMaxAc:11
    },
    ellingo:{
        name:'ElLingo',
        soc:['sensor.ellingo_broker_battery_level','sensor.ellingo_battery_level'],
        target:['sensor.ellingo_broker_charge_limit_actual','number.ellingo_charge_limit_2'],
        location:['sensor.ellingo_broker_location','device_tracker.ellingo_location'],
        connected:['binary_sensor.ellingo_broker_charge_cable_connected','binary_sensor.ellingo_charge_cable'],
        charging:['sensor.ellingo_broker_charger_state','sensor.ellingo_charging'],
        capacity:'input_number.ellingo_optimizer_battery_capacity_kwh',
        maxAc:'input_number.ellingo_optimizer_max_ac_kw',
        defaultCapacity:100,
        defaultMaxAc:16
    }
};

const actions=[];
const logs=[];
const summaries={};

if (!priceToleranceInitialized) {
    actions.push(setNumber('input_number.ev_charge_price_equal_tolerance_ore_per_kwh',0.5));
    actions.push(setBool('input_boolean.ev_charge_price_tolerance_initialized',true));
}

if (!configInitialized) {
    actions.push(setBool('input_boolean.ev_site_anemonevej_enabled',true));
    actions.push(setBool('input_boolean.ev_site_ia_moellersvej_enabled',true));
    actions.push(setNumber('input_number.ev_site_anemonevej_grid_limit_amps',26));
    actions.push(setNumber('input_number.ev_site_ia_moellersvej_grid_limit_amps',0));
    actions.push(setNumber('input_number.ev_charge_long_trip_safety_margin_minutes',15));
    actions.push(setText('input_text.ev_site_anemonevej_price_source','real_energy'));
    actions.push(setText('input_text.ev_site_ia_moellersvej_price_source','real_energy'));
    actions.push(setNumber('input_number.blue_flux_optimizer_battery_capacity_kwh',75));
    actions.push(setNumber('input_number.blue_flux_optimizer_max_ac_kw',11));
    actions.push(setNumber('input_number.ellingo_optimizer_battery_capacity_kwh',100));
    actions.push(setNumber('input_number.ellingo_optimizer_max_ac_kw',16));
    actions.push(setBool('input_boolean.ev_charge_optimizer_config_initialized',true));
}

// First pass: collect both cars so site sharing can be estimated.
const C={};
for (const [key,car] of Object.entries(cars)) {
    const socPick=firstNumber(car.soc);
    const targetPick=firstNumber(car.target);
    const locationPick=firstState(car.location);
    const connectedPick=firstBool(car.connected);
    const chargingPick=firstState(car.charging);

    const soc=socPick.value;
    const target=targetPick.value;
    const location=locationPick.value;
    const connected=connectedPick.value===true;
    const cSite=controlSite(location);
    const eSite=estimationSite(location);
    const controlCfg=cSite!=='none'?sites[cSite]:null;
    const estimateCfg=sites[eSite];
    const controlEligible=cSite!=='none' && !!controlCfg?.enabled && connected;
    const capacity=configInitialized ? num(car.capacity) : car.defaultCapacity;
    const maxAc=configInitialized ? num(car.maxAc) : car.defaultMaxAc;
    const eSiteKw=siteKw(estimateCfg?.amps);
    const soloKw=(maxAc && eSiteKw) ? Math.min(maxAc,eSiteKw) : null;
    const missingKwh=(soc!==null && target!==null && capacity!==null)
        ? Math.max(0,capacity*Math.max(0,target-soc)/100) : null;

    C[key]={
        key,car,socPick,targetPick,locationPick,connectedPick,chargingPick,
        soc,target,location,connected,cSite,eSite,controlCfg,estimateCfg,
        controlEligible,capacity,maxAc,soloKw,missingKwh,band:bandFor(soc,target)
    };
}

// Conservative load-share planning power: if two cars are simultaneously eligible on the
// same site, reserve an equal site share for each. This prevents optimistic deadline estimates.
const eligibleBySite={};
for (const st of Object.values(C)) {
    if (!st.controlEligible || st.soc===null || st.target===null || st.soc>=st.target) continue;
    if (!eligibleBySite[st.cSite]) eligibleBySite[st.cSite]=[];
    eligibleBySite[st.cSite].push(st.key);
}
for (const st of Object.values(C)) {
    const cfg=st.controlCfg;
    const skw=siteKw(cfg?.amps);
    const count=(eligibleBySite[st.cSite]||[]).length || 1;
    st.planningKw=(st.controlEligible && st.maxAc && skw)
        ? Math.min(st.maxAc,skw/count)
        : st.soloKw;
    st.estimateKw=st.controlEligible ? st.planningKw : st.soloKw;
    st.durationH=(st.estimateKw && st.missingKwh!==null) ? st.missingKwh/st.estimateKw : null;
    st.estimateValid=st.durationH!==null && Number.isFinite(st.durationH);
}

function prepareSlots(record) {
    if (!record || !Array.isArray(record.slots)) return [];
    return record.slots.map((x,i)=>{
        const s=new Date(x.start);
        const e=new Date(x.end);
        const p=Number(x.price);
        if (!Number.isFinite(s.getTime()) || !Number.isFinite(e.getTime()) || !Number.isFinite(p) || e<=s) return null;
        return {i,start:s,end:e,price:p};
    }).filter(Boolean).sort((a,b)=>a.start-b.start);
}

function makePlanner(st,slots,ruleDeadline,longTrip) {
    const power=st.planningKw;
    const soc=st.soc;
    const target=st.target;
    const capacity=st.capacity;
    if (!power || !capacity || soc===null || target===null || soc>=target) {
        return {valid:false,reason:'No usable charging demand/power.',selected:[]};
    }

    const usable=slots
        .filter(x=>x.end>now)
        .map(x=>({
            ...x,
            availStart:x.start<now?new Date(now):x.start
        }))
        .filter(x=>x.end>x.availStart);

    if (!usable.length) return {valid:false,reason:'No future price slots are available.',selected:[]};

    const alloc=new Map(); // slot index -> planned kWh (cost calculation)
    const selected=new Set();
    const stages=[];
    let failReason='';
    let finalDeadline=null;

    const energyToPct=(pct)=>capacity*Math.max(0,Math.min(target,pct)-soc)/100;
    const slotCapUntil=(x,deadline)=>{
        const e=deadline && deadline<x.end ? deadline : x.end;
        if (e<=x.availStart) return 0;
        return power*(e-x.availStart)/3600000;
    };
    const allocatedUntil=(deadline)=>{
        let sum=0;
        for (const x of usable) {
            const a=alloc.get(x.i)||0;
            if (a<=0) continue;
            sum += Math.min(a,slotCapUntil(x,deadline));
        }
        return sum;
    };
    const allocate=(requiredCum,deadline,forcedChronological,label)=>{
        finalDeadline=deadline || finalDeadline;
        let have=allocatedUntil(deadline);
        let deficit=Math.max(0,requiredCum-have);
        if (deficit<=0.0001) {
            stages.push({label,required:requiredCum,deadline:iso(deadline),ok:true});
            return true;
        }

        let candidates=usable.filter(x=>slotCapUntil(x,deadline)>(alloc.get(x.i)||0)+0.000001);
        if (forcedChronological) {
            candidates.sort((a,b)=>a.availStart-b.availStart);
        } else {
            // Stable price-tolerance ordering:
            // 1) Find the cheapest remaining price.
            // 2) Treat every slot <= cheapest + tolerance as the SAME effective price.
            // 3) Inside that group, always prefer the earliest slot.
            // 4) Remove that group and repeat for the next price level.
            //
            // This avoids the non-transitive comparator problem where A≈B and B≈C,
            // but A is not≈C, which could make plans change between recalculations.
            const remaining=[...candidates];
            const ordered=[];
            const epsilon=1e-9;

            while (remaining.length) {
                const minPrice=Math.min(...remaining.map(x=>x.price));
                const maxEquivalent=minPrice+priceEqualToleranceDkk+epsilon;

                const group=remaining
                    .filter(x=>x.price<=maxEquivalent)
                    .sort((a,b)=>
                        (a.availStart-b.availStart) ||
                        (a.price-b.price)
                    );

                ordered.push(...group);

                const groupIds=new Set(group.map(x=>x.i));
                for (let i=remaining.length-1;i>=0;i--) {
                    if (groupIds.has(remaining[i].i)) remaining.splice(i,1);
                }
            }

            candidates.splice(0,candidates.length,...ordered);
        }

        for (const x of candidates) {
            if (deficit<=0.0001) break;
            const cap=slotCapUntil(x,deadline);
            const used=alloc.get(x.i)||0;
            const room=Math.max(0,cap-used);
            if (!room) continue;
            const take=Math.min(room,deficit);
            alloc.set(x.i,used+take);
            selected.add(x.i);
            deficit-=take;
        }

        const ok=deficit<=0.0001;
        stages.push({label,required:requiredCum,deadline:iso(deadline),ok,remaining:Math.max(0,deficit)});
        if (!ok && !failReason) failReason=`Insufficient known priced capacity for ${label}.`;
        return ok;
    };
    const selectedEnd=()=>{
        const arr=usable.filter(x=>selected.has(x.i));
        return arr.length?new Date(Math.max(...arr.map(x=>x.end.getTime()))):new Date(now);
    };

    // Stage 1: <5% must charge immediately. Cheapest-price sorting is intentionally disabled.
    if (soc<5 && target>soc) {
        const p=Math.min(5,target);
        const req=energyToPct(p);
        // Use a generous deadline bounded by available price horizon; chronological allocation makes it immediate.
        const d=addHours(now,6);
        allocate(req,d,true,`immediate_to_${p}`);
    }

    // Stage 2: reach 10% within four hours. If we started below 5%, the 4h window starts
    // from the estimated completion of the immediate 5% stage.
    if (soc<10 && target>5) {
        const p=Math.min(10,target);
        let d;
        if (soc<5) d=addHours(selectedEnd(),4);
        else d=(st.band==='5_to_10' && ruleDeadline)?ruleDeadline:addHours(now,4);
        allocate(energyToPct(p),d,false,`to_${p}_within_4h`);
    }

    // Stage 3: reach up to 50% by next 07:00; a long-trip final deadline may be earlier.
    let reach50=null;
    if (soc<50 && target>10) {
        const p=Math.min(50,target);
        let d=nextClock(7,0,now);
        if (longTrip && ruleDeadline) {
            const safe=new Date(ruleDeadline.getTime()-marginMin*60000);
            d=minDate(d,safe);
        }
        allocate(energyToPct(p),d,false,`to_${p}_by_morning`);
        if (p===50) reach50=selectedEnd();
    }

    // Final target.
    if (target>50) {
        let d;
        if (longTrip) {
            d=ruleDeadline ? new Date(ruleDeadline.getTime()-marginMin*60000) : nextClock(6,30,now);
        } else if (soc>=50 && ruleDeadline) {
            d=ruleDeadline;
        } else {
            d=addHours(reach50 || selectedEnd() || now,24);
        }
        allocate(st.missingKwh,d,false,`to_target_${target}`);
        finalDeadline=d;
    } else if (!finalDeadline) {
        // Targets <=50 are completed by their relevant stage above.
        finalDeadline=selectedEnd();
    }

    const arr=usable.filter(x=>selected.has(x.i)).sort((a,b)=>a.availStart-b.availStart);
    const totalAllocated=[...alloc.values()].reduce((a,b)=>a+b,0);
    const totalCost=arr.reduce((sum,x)=>sum+(alloc.get(x.i)||0)*x.price,0);
    const coverageEnd=new Date(Math.max(...usable.map(x=>x.end.getTime())));
    const needCoverageUntil=finalDeadline || selectedEnd();
    const coverageComplete=coverageEnd>=needCoverageUntil;

    // Unknown future prices are NOT a reason to wait by themselves.
    // If currently known priced slots can already deliver all required energy,
    // accept the cheapest known complete plan. We prefer a known good price now
    // over gambling that tomorrow's unknown price will be cheaper.
    let complete=stages.every(x=>x.ok);
    const horizonIncomplete=!!(needCoverageUntil && !coverageComplete);

    const planStart=arr.length?arr[0].availStart:null;
    const planEnd=arr.length?arr[arr.length-1].end:null;

    // Human/log summary of selected 15-minute periods. Adjacent periods with identical price are merged.
    const merged=[];
    for (const x of arr) {
        const a=alloc.get(x.i)||0;
        if (a<=0) continue;
        const prev=merged[merged.length-1];
        if (prev && prev.end.getTime()===x.availStart.getTime() && Math.abs(prev.price-x.price)<1e-9) {
            prev.end=x.end;
            prev.kwh+=a;
        } else {
            merged.push({start:x.availStart,end:x.end,price:x.price,kwh:a});
        }
    }
    const compact=merged.map(x=>`${iso(x.start)}..${iso(x.end)} @${x.price.toFixed(4)} (${x.kwh.toFixed(2)}kWh)`).join(' | ');

    const actionable=arr.length>0;
    let planReason;
    if (complete && horizonIncomplete) {
        planReason='Complete plan calculated from currently known prices; unknown future prices are not required to meet the target.';
    } else if (complete) {
        planReason='Price plan calculated.';
    } else if (actionable && horizonIncomplete) {
        planReason='Known price horizon cannot yet complete the full target. Use the known charging periods now and recalculate when new prices arrive.';
    } else {
        planReason=failReason||'Price plan incomplete.';
    }

    return {
        valid:complete,
        actionable,
        provisional:!complete && actionable,
        horizonIncomplete,
        reason:planReason,
        planStart,planEnd,totalCost,totalAllocated,coverageEnd,finalDeadline,
        averagePrice:totalAllocated>0?totalCost/totalAllocated:null,
        selected:arr.map(x=>({
            start:iso(x.availStart),end:iso(x.end),price:x.price,kwh:round2(alloc.get(x.i)||0)
        })),
        compact,
        stages
    };
}

for (const [key,st] of Object.entries(C)) {
    const {car}=st;
    const anchorEntity=`input_text.${key}_charge_rule_anchor_value`;
    const deadlineEntity=`input_datetime.${key}_charge_rule_deadline_value`;
    const longTripEntity=`input_boolean.${key}_optimizer_long_trip_active`;

    const previousAnchor=state(anchorEntity)||'none';
    const previousDeadline=parseHaDateTime(state(deadlineEntity));
    const previousLongTrip=bool(longTripEntity)===true;
    const longTrip=st.target!==null && st.target>=85;

    let anchor=previousAnchor;
    let deadline=previousDeadline;

    if (longTrip) {
        if (previousAnchor!=='long_trip_0630' || !previousDeadline) {
            deadline=nextClock(6,30,now);
            anchor='long_trip_0630';
        } else anchor='long_trip_0630';
    } else {
        if (previousLongTrip || previousAnchor==='long_trip_0630') {
            anchor='none';
            deadline=null;
        }

        if (st.band==='target_reached' || st.band==='unknown') {
            anchor=st.band;
            deadline=null;
        } else if (st.band==='below_5') {
            if (anchor!=='below_5_immediate' || !deadline) {
                anchor='below_5_immediate';
                deadline=new Date(now);
            }
        } else if (!st.controlEligible) {
            anchor=`${st.band}_waiting_for_site`;
            deadline=null;
        } else if (st.band==='5_to_10') {
            if (anchor!=='5_to_10_4h' || !deadline) {
                anchor='5_to_10_4h';
                deadline=addHours(now,4);
            }
        } else if (st.band==='10_to_50') {
            if (anchor!=='10_to_50_0700' || !deadline) {
                anchor='10_to_50_0700';
                deadline=nextClock(7,0,now);
            }
        } else if (st.band==='above_50') {
            if (anchor!=='above_50_24h' || !deadline) {
                anchor='above_50_24h';
                deadline=addHours(now,24);
            }
        }
    }

    const priceSource=st.estimateCfg?.priceSource || 'unknown';
    const priceRecord=priceSources[priceSource];
    const slots=prepareSlots(priceRecord);

    let plan=null;
    if (st.controlEligible && st.estimateValid && st.band!=='target_reached' && slots.length) {
        plan=makePlanner(st,slots,deadline,longTrip);
    }

    let optState='planning';
    let reason='';

    if (mode==='Disabled') {
        optState='disabled';
        reason='Optimizer mode is Disabled.';
    } else if (st.soc===null || st.target===null || st.location===null) {
        optState='vehicle_data_missing';
        reason='Missing SoC, target or location data.';
    } else if (st.band==='target_reached') {
        optState='target_reached';
        reason=`SoC ${st.soc}% is at or above target ${st.target}%.`;
    } else if (!st.controlEligible) {
        optState=st.cSite==='none'?'away':'not_connected';
        reason=st.cSite==='none'
            ? `No exact control site match for location '${st.location}'. Estimation uses ${st.eSite}.`
            : `Car is at ${st.cSite}, but the charge cable is not reported connected.`;
    } else if (!st.estimateValid) {
        optState='estimate_unavailable';
        reason='Missing usable battery capacity, max AC power or site grid limit.';
    } else if (!slots.length) {
        optState='waiting_for_price_adapter';
        reason=`No normalized 15-minute '${priceSource}' slots are cached yet.`;
    } else if (plan && plan.valid) {
        optState=longTrip?'plan_ready_long_trip':'plan_ready';
        reason=`${plan.reason} ${plan.selected.length} slots, first ${iso(plan.planStart)}, end ${iso(plan.planEnd)}, est. ${round2(plan.totalCost)} DKK.`;
    } else if (plan && plan.actionable && plan.horizonIncomplete) {
        const cov=plan.coverageEnd?iso(plan.coverageEnd):'unknown';
        optState='provisional_known_price_plan';
        reason=`${plan.reason} Price coverage currently ends ${cov}.`;
    } else if (plan) {
        const cov=plan.coverageEnd?iso(plan.coverageEnd):'unknown';
        optState='plan_incomplete';
        reason=`${plan.reason} Price coverage ends ${cov}.`;
    } else {
        optState='planning';
        reason='Planner has not produced a plan.';
    }

