    actions.push(setBool(`input_boolean.${key}_optimizer_charge_authorized`,false));
    actions.push(setBool(`input_boolean.${key}_charge_estimate_valid`,st.estimateValid));
    actions.push(setBool(`input_boolean.${key}_charge_plan_valid`,!!plan?.valid));
    actions.push(setBool(longTripEntity,longTrip));

    actions.push(setText(`input_text.${key}_charge_site_value`,st.cSite));
    actions.push(setText(`input_text.${key}_charge_estimation_site_value`,st.eSite));
    actions.push(setText(`input_text.${key}_charge_price_source_value`,priceSource));
    actions.push(setText(`input_text.${key}_charge_rule_value`,longTrip?'long_trip':st.band));
    actions.push(setText(`input_text.${key}_charge_optimizer_state_value`,optState));
    actions.push(setText(`input_text.${key}_charge_optimizer_reason_value`,reason));
    actions.push(setText(anchorEntity,anchor));

    if (deadline) actions.push(setDateTime(deadlineEntity,deadline));
    if (st.missingKwh!==null) actions.push(setNumber(`input_number.${key}_charge_missing_kwh_value`,round2(st.missingKwh)));
    if (st.estimateKw!==null) actions.push(setNumber(`input_number.${key}_charge_estimated_power_kw_value`,round2(st.estimateKw)));
    if (st.estimateValid) actions.push(setNumber(`input_number.${key}_charge_estimated_duration_value`,round2(st.durationH)));

    const slotText=(plan?.valid || plan?.actionable) ? plannedSlotsText(plan) : 'none';
    actions.push(setText(`input_text.${key}_charge_planned_slots_value`,slotText));

    if (plan?.valid) {
        actions.push(setNumber(`input_number.${key}_charge_estimated_cost_value`,round2(plan.totalCost)));
        if (plan.planStart) actions.push(setDateTime(`input_datetime.${key}_charge_plan_start_value`,plan.planStart));
        if (plan.planEnd) actions.push(setDateTime(`input_datetime.${key}_charge_plan_end_value`,plan.planEnd));
    } else if (plan?.actionable) {
        // Start/end describe the currently known provisional charging plan.
        // Total cost to final target is not yet knowable, therefore cost remains 0 until a complete plan exists.
        if (plan.planStart) actions.push(setDateTime(`input_datetime.${key}_charge_plan_start_value`,plan.planStart));
        if (plan.planEnd) actions.push(setDateTime(`input_datetime.${key}_charge_plan_end_value`,plan.planEnd));
        actions.push(setNumber(`input_number.${key}_charge_estimated_cost_value`,0));
    } else {
        actions.push(setNumber(`input_number.${key}_charge_estimated_cost_value`,0));
    }

    const logFields=[
        now.toISOString(),
        'price_plan_v1_2',
        key,
        safeText(car.name),
        safeText(mode),
        st.soc??'',
        st.target??'',
        safeText(st.location||''),
        st.cSite,
        st.eSite,
        st.connected?'1':'0',
        safeText(st.chargingPick.value||''),
        longTrip?'long_trip':st.band,
        longTrip?'1':'0',
        deadline?deadline.toISOString():'',
        st.missingKwh!==null?st.missingKwh.toFixed(2):'',
        st.estimateKw!==null?st.estimateKw.toFixed(2):'',
        st.estimateValid?st.durationH.toFixed(2):'',
        priceSource,
        priceRecord?.origin||'',
        slots.length,
        plan?.valid?'1':'0',
        plan?.planStart?iso(plan.planStart):'',
        plan?.planEnd?iso(plan.planEnd):'',
        plan?.totalCost!==undefined?round2(plan.totalCost).toFixed(2):'',
        plan?.averagePrice!==null && plan?.averagePrice!==undefined?plan.averagePrice.toFixed(4):'',
        plan?.selected?.length||0,
        safeText(plan?.compact||'',500),
        optState,
        safeText(reason,500),
        safeText(st.socPick.entity||''),
        safeText(st.targetPick.entity||''),
        safeText(st.locationPick.entity||''),
        safeText(st.connectedPick.entity||'')
    ];
    logs.push({payload:logFields.map(v=>`"${safeText(v,800)}"`).join(';')});

    summaries[key]={
        soc:st.soc,target:st.target,location:st.location,
        controlSite:st.cSite,estimationSite:st.eSite,connected:st.connected,
        controlEligible:st.controlEligible,
        rule:longTrip?'long_trip':st.band,longTrip,
        deadline:deadline?deadline.toISOString():null,
        missingKwh:st.missingKwh,
        estimatedPowerKw:st.estimateKw,
        estimatedDurationH:st.durationH,
        priceSource,
        priceOrigin:priceRecord?.origin||null,
        priceSlots:slots.length,
        priceEqualToleranceOrePerKwh:priceEqualToleranceOre,
        planValid:!!plan?.valid,
        planActionable:!!plan?.actionable,
        planProvisional:!!plan?.provisional,
        planStart:plan?.planStart?iso(plan.planStart):null,
        planEnd:plan?.planEnd?iso(plan.planEnd):null,
        estimatedCost:plan?.valid?round2(plan.totalCost):null,
        selectedSlots:plan?.selected||[],
        stages:plan?.stages||[],
        optimizerState:optState,
        reason
    };
}

// Executor calculates operational health and authorization separately.
actions.push(setDateTime('input_datetime.ev_charge_optimizer_last_calculation_value',now));
flow.set('evopt_latest_summary', {updated:Date.now(), cars:summaries});

return [actions,logs,[{payload:summaries,_evopt_plan_update:true}]];

