    if (['on','true','yes','connected','charging'].includes(v)) return true;
    if (['off','false','no','disconnected','stopped','complete'].includes(v)) return false;
    return null;
}
function getNum(entity) {
    const s=getState(entity);
    if (s===null) return null;
    const n=Number(String(s).replace(',','.'));
    return Number.isFinite(n) ? n : null;
}
function firstNum(list) {
    for (const e of list) { const n=getNum(e); if (n!==null) return {value:n,entity:e}; }
    return {value:null,entity:null};
}
function firstState(list) {
    for (const e of list) { const s=getState(e); if (s!==null) return {value:s,entity:e}; }
    return {value:null,entity:null};
}
function firstBool(list) {
    for (const e of list) { const b=getBool(e); if (b!==null) return {value:b,entity:e}; }
    return {value:null,entity:null};
}
function safe(v,max=800) {
    return String(v??'').replace(/[\r\n]+/g,' ').replace(/"/g,"'").slice(0,max);
}
function headerRow(type,key,car,mode,summary,reason) {
    const fields=[
        new Date().toISOString(), type, key, car.name, mode,
        summary?.soc??'', summary?.target??'', safe(summary?.location||''),
        summary?.controlSite||'', summary?.estimationSite||'',
        summary?.connected?'1':'0', '',
        summary?.rule||'', summary?.longTrip?'1':'0', summary?.deadline||'',
        summary?.missingKwh??'', summary?.estimatedPowerKw??'', summary?.estimatedDurationH??'',
        summary?.priceSource||'', summary?.priceOrigin||'', summary?.priceSlots??'',
        summary?.planValid?'1':'0', summary?.planStart||'', summary?.planEnd||'',
        summary?.estimatedCost??'', '', summary?.selectedSlots?.length||'',
        safe((summary?.selectedSlots||[]).map(x=>`${x.start}..${x.end} @${x.price}`).join(' | '),500),
        type, safe(reason,500), '', '', '', ''
    ];
    return {payload:fields.map(v=>`"${safe(v)}"`).join(';')};
}
function setBoolMsg(entity_id,on) {
    return {ha_action:on?'input_boolean.turn_on':'input_boolean.turn_off',entity_id};
}
function setNumMsg(entity_id,value) {
    return {ha_action:'input_number.set_value',entity_id,value:Number(value)};
}
function setTextMsg(entity_id,value) {
    return {ha_action:'input_text.set_value',entity_id,value:String(value)};
}
function setDateTimeMsg(entity_id,d) {
    const pad=n=>String(n).padStart(2,'0');
    const s=`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
    return {ha_action:'input_datetime.set_datetime',entity_id,value:s};
}
function desiredNow(summary, nowMs) {
    if (!summary || !Array.isArray(summary.selectedSlots)) return false;
    return summary.selectedSlots.some(s=>{
        const a=Date.parse(s.start), b=Date.parse(s.end);
        return Number.isFinite(a)&&Number.isFinite(b)&&nowMs>=a&&nowMs<b;
    });
}
function chargingActual(car) {
    const sw=getBool(car.switchEntity);
    if (sw!==null) return sw;
    const st=firstState(car.chargingEntities).value;
    if (st===null) return null;
    const v=String(st).toLowerCase();
    if (v.includes('charg') && !v.includes('not') && !v.includes('dis')) return true;
    if (['stopped','complete','disconnected','no_power'].some(x=>v.includes(x))) return false;
    return null;
}
function normalizeLocation(s) {
    return String(s||'').trim().toLowerCase().replace(/_/g,' ').replace(/\s+/g,' ');
}
function siteFromLocation(location) {
    const l=normalizeLocation(location);
    if (l==='home') return 'anemonevej';
    if (['i.a. møllersvej','i.a møllersvej','i.a. mollersvej','i.a mollersvej'].includes(l)) return 'ia_moellersvej';
    return 'none';
}
function sitePriceSource(site) {
    if (site==='anemonevej') return getState('input_text.ev_site_anemonevej_price_source') || 'real_energy';
    if (site==='ia_moellersvej') return getState('input_text.ev_site_ia_moellersvej_price_source') || 'real_energy';
    return null;
}
function siteKw(site) {
    let amps=null;
    if (site==='anemonevej') amps=getNum('input_number.ev_site_anemonevej_grid_limit_amps');
    if (site==='ia_moellersvej') amps=getNum('input_number.ev_site_ia_moellersvej_grid_limit_amps');
    return amps && amps>0 ? 3*230*amps/1000 : null;
}
function currentCheapWindow(source,threshold,nowMs) {
    const rec=priceSources[source];
    if (!rec || !Array.isArray(rec.slots)) return {known:false,cheap:false,price:null,end:null};
    const slots=rec.slots.map(x=>({
        start:Date.parse(x.start),end:Date.parse(x.end),price:Number(x.price)
    })).filter(x=>Number.isFinite(x.start)&&Number.isFinite(x.end)&&Number.isFinite(x.price)&&x.end>x.start)
      .sort((a,b)=>a.start-b.start);

    let idx=slots.findIndex(x=>nowMs>=x.start && nowMs<x.end);
    if (idx<0) return {known:false,cheap:false,price:null,end:null};

    const cur=slots[idx];
    if (!(cur.price<threshold)) return {known:true,cheap:false,price:cur.price,end:new Date(cur.end)};

    let end=cur.end;
    for (let i=idx+1;i<slots.length;i++) {
        const s=slots[i];
        // contiguous price slots only
        if (Math.abs(s.start-end)>2000) break;
        if (!(s.price<threshold)) break;
        end=s.end;
    }
    return {known:true,cheap:true,price:cur.price,end:new Date(end)};
}
function approx(a,b,tol=0.25) {
    return Number.isFinite(a)&&Number.isFinite(b)&&Math.abs(a-b)<=tol;
}

const cars={
    blue_flux:{
        name:'Blue Flux',
        switchEntity:'switch.blue_flux_charge',
        limitEntity:'number.blue_flux_charge_limit',
        socEntities:['sensor.blue_flux_broker_battery_level'],
        targetEntities:['sensor.blue_flux_broker_charge_limit_actual'],
        locationEntities:['sensor.blue_flux_broker_location'],
        chargingEntities:['sensor.blue_flux_broker_charger_state'],
        cableEntities:['binary_sensor.blue_flux_broker_charge_cable_connected'],
        capacityEntity:'input_number.blue_flux_optimizer_battery_capacity_kwh',
        maxAcEntity:'input_number.blue_flux_optimizer_max_ac_kw'
    },
    ellingo:{
        name:'ElLingo',
        switchEntity:'switch.ellingo_charge',
        limitEntity:'number.ellingo_charge_limit_2',
        socEntities:['sensor.ellingo_broker_battery_level'],
        targetEntities:['sensor.ellingo_broker_charge_limit_actual'],
        locationEntities:['sensor.ellingo_broker_location'],
        chargingEntities:['sensor.ellingo_broker_charger_state'],
        cableEntities:['binary_sensor.ellingo_broker_charge_cable_connected'],
        capacityEntity:'input_number.ellingo_optimizer_battery_capacity_kwh',
        maxAcEntity:'input_number.ellingo_optimizer_max_ac_kw'
    }
};

const latest=flow.get('evopt_latest_summary');
const summaries=latest?.cars || {};
const summaryAgeMs=latest?.updated ? Date.now()-latest.updated : Infinity;
const mode=getState('input_select.ev_charge_optimizer_mode') || 'Log only';
const production=mode==='Production';
const watchdog=msg._watchdog===true;
const nowMs=Date.now();

// ------------------------------------------------------------
// Cheap Boost configuration
// ------------------------------------------------------------
const boostConfigInitialized=getBool('input_boolean.ev_charge_cheap_boost_config_initialized')===true;
const boostEnabledState=getBool('input_boolean.ev_charge_cheap_boost_enabled');
const boostEnabled=boostConfigInitialized ? boostEnabledState===true : true;
const boostThreshold=boostConfigInitialized
    ? (getNum('input_number.ev_charge_cheap_boost_price_threshold_dkk_per_kwh') ?? 0.50)
    : 0.50;
const boostTarget=boostConfigInitialized
    ? (getNum('input_number.ev_charge_cheap_boost_target_pct') ?? 80)
    : 80;

const helperMsgs=[];
const limitMsgs=[];
const onMsgs=[], offMsgs=[], logMsgs=[];

// Log a blocked scheduled start once per slot/reason, rather than silently doing nothing.
function logBlockedOnce(key,car,s,reason,blockId) {
    const ctxKey=`evopt_blocked_${key}`;
    const prev=flow.get(ctxKey);
    if (prev!==blockId) {
        flow.set(ctxKey,blockId);
        logMsgs.push(headerRow('executor_start_blocked',key,car,mode,s,reason));
    }
}

if (!boostConfigInitialized) {
    helperMsgs.push(setNumMsg('input_number.ev_charge_cheap_boost_price_threshold_dkk_per_kwh',0.50));
    helperMsgs.push(setNumMsg('input_number.ev_charge_cheap_boost_target_pct',80));
    helperMsgs.push(setBoolMsg('input_boolean.ev_charge_cheap_boost_enabled',true));
    helperMsgs.push(setBoolMsg('input_boolean.ev_charge_cheap_boost_config_initialized',true));
}

// ------------------------------------------------------------
// Build live car data first so shared-site power can be conservative.
// ------------------------------------------------------------
const live={};
for (const [key,car] of Object.entries(cars)) {
    const soc=firstNum(car.socEntities).value;
    const limit=firstNum(car.targetEntities).value;
    const location=firstState(car.locationEntities).value;
    const site=siteFromLocation(location);
    const cable=firstBool(car.cableEntities).value===true;
    const source=sitePriceSource(site);
    live[key]={
        key,car,soc,limit,location,site,cable,source,
        capacity:getNum(car.capacityEntity),
        maxAc:getNum(car.maxAcEntity)
    };
}

// Conservative potential contenders at a site. If both connected cars could charge,
// reserve half of site capacity for each rather than assuming full site power.
for (const x of Object.values(live)) {
    let contenders=0;
    for (const y of Object.values(live)) {
        if (y.site===x.site && y.site!=='none' && y.cable && y.soc!==null && y.limit!==null) {
            if (y.soc<y.limit || (y.limit<boostTarget && y.soc<boostTarget)) contenders++;
        }
    }
    contenders=Math.max(1,contenders);
    const skw=siteKw(x.site);
    x.availableKw=(x.maxAc && skw) ? Math.min(x.maxAc,skw/contenders) : null;
}

// ------------------------------------------------------------
// Operational health for normal planner.
// ------------------------------------------------------------
// Planner fallback recalculates every 30 minutes.
// A 10-minute limit could invalidate a perfectly valid scheduled slot between planner runs.
// Use 40 minutes = 30-minute planner cadence + 10-minute safety margin.
const maxSummaryAgeMs=40*60*1000;
let healthy=summaryAgeMs < maxSummaryAgeMs;
for (const [key,s] of Object.entries(summaries)) {
    if (!s) continue;
    if (s.controlEligible && s.soc!==null && s.target!==null && Number(s.soc)<Number(s.target)) {
        if (!(s.planValid || s.planActionable) || !s.priceSlots) healthy=false;
    }
}
if (!production) healthy=false;

helperMsgs.push(setBoolMsg('input_boolean.ev_charge_optimizer_healthy_value',healthy));

// ------------------------------------------------------------
// Cheap Boost state machine per car.
// ------------------------------------------------------------
const boost={};

for (const [key,x] of Object.entries(live)) {
    const car=x.car;
    const s=summaries[key];
    const actual=chargingActual(car);

    let active=getBool(`input_boolean.${key}_cheap_boost_active`)===true;
    let suppressed=getBool(`input_boolean.${key}_cheap_boost_suppressed`)===true;
    let original=getNum(`input_number.${key}_cheap_boost_original_limit_value`);
    const priceWin=x.source ? currentCheapWindow(x.source,boostThreshold,nowMs) :
                              {known:false,cheap:false,price:null,end:null};

    const validSite=x.site!=='none';
    const eligible=validSite && x.cable;
    const dataOk=x.soc!==null && x.limit!==null && x.capacity!==null && x.availableKw!==null && x.availableKw>0;
    let boostAuthorized=false;
    let status='inactive';
    let reason='';

    // End of a cheap window resets suppression, allowing evaluation next time price falls.
    if (!priceWin.cheap && suppressed) {
        suppressed=false;
        helperMsgs.push(setBoolMsg(`input_boolean.${key}_cheap_boost_suppressed`,false));
    }

    // Manual charge-limit change protection while boost is active:
    // - live limit == boost target: normal active state
    // - live limit == original: may be command propagation / restore already completed
    // - any other value: user/Tesla changed it, so cancel boost WITHOUT restoring original
    if (active && x.limit!==null && original!==null &&
        !approx(x.limit,boostTarget) && !approx(x.limit,original)) {
        active=false;
        suppressed=false;
        helperMsgs.push(setBoolMsg(`input_boolean.${key}_cheap_boost_active`,false));
        helperMsgs.push(setBoolMsg(`input_boolean.${key}_cheap_boost_suppressed`,false));
        status='manual_override';
        reason=`Charge limit changed externally from boost target ${boostTarget}% to ${x.limit}%. Old ${original}% limit will NOT be restored.`;
        helperMsgs.push(setTextMsg(`input_text.${key}_cheap_boost_status_value`,status));
        logMsgs.push(headerRow('cheap_boost_manual_override',key,car,mode,s,reason));
    }

    // Restore conditions for an existing boost.
    if (active) {
        let restoreReason=null;

        if (!production) restoreReason='Optimizer left Production mode.';
        else if (!boostEnabled) restoreReason='Cheap Boost was disabled.';
        else if (!eligible) restoreReason='Car left a valid charging site or cable disconnected.';
        else if (!priceWin.known) restoreReason='Current real_energy price is unavailable.';
        else if (!priceWin.cheap) restoreReason=`Price ${priceWin.price?.toFixed(4)} DKK/kWh is no longer below ${boostThreshold.toFixed(2)}.`;
        else if (x.soc!==null && x.soc>=boostTarget) restoreReason=`Boost target ${boostTarget}% reached.`;

        if (restoreReason) {
            // Restore only if the car is still at the temporary boost limit (or still at original).
            // If another value is present, treat it as an external/manual change and preserve it.
            if (original!==null && x.limit!==null && approx(x.limit,boostTarget)) {
                limitMsgs.push({entity_id:car.limitEntity,value:original,car:key,reason:'cheap_boost_restore'});
            }
            active=false;
            helperMsgs.push(setBoolMsg(`input_boolean.${key}_cheap_boost_active`,false));
            status='restoring';
            reason=`${restoreReason} Restoring original charge limit ${original}%.`;
            helperMsgs.push(setTextMsg(`input_text.${key}_cheap_boost_status_value`,status));
            logMsgs.push(headerRow('cheap_boost_restore',key,car,mode,s,reason));
        }
    }

    // Activate a new boost only while price is currently cheap.
    if (!active && !suppressed && production && boostEnabled && eligible &&
        priceWin.known && priceWin.cheap && dataOk &&
        x.limit<boostTarget && x.soc<boostTarget) {

        const cheapHours=Math.max(0,(priceWin.end.getTime()-nowMs)/3600000);
        const kwhToBoost=x.capacity*Math.max(0,boostTarget-x.soc)/100;
        const hoursToBoost=kwhToBoost/x.availableKw;
        const alreadyAtNormalTarget=x.soc>=x.limit;
        const canReachBoost=hoursToBoost<=cheapHours + 1e-6;

        if (alreadyAtNormalTarget || canReachBoost) {
            original=x.limit;
            active=true;
            helperMsgs.push(setNumMsg(`input_number.${key}_cheap_boost_original_limit_value`,original));
            helperMsgs.push(setBoolMsg(`input_boolean.${key}_cheap_boost_active`,true));
            helperMsgs.push(setBoolMsg(`input_boolean.${key}_cheap_boost_suppressed`,false));
            helperMsgs.push(setDateTimeMsg(`input_datetime.${key}_cheap_boost_window_end_value`,priceWin.end));
            status='active';
            reason=alreadyAtNormalTarget
                ? `Normal target ${original}% already reached. Price ${priceWin.price.toFixed(4)} < ${boostThreshold.toFixed(2)} DKK/kWh; boost to ${boostTarget}% until ${priceWin.end.toISOString()}.`
                : `Can reach ${boostTarget}% inside current cheap window (${hoursToBoost.toFixed(2)}h required, ${cheapHours.toFixed(2)}h available).`;
            helperMsgs.push(setTextMsg(`input_text.${key}_cheap_boost_status_value`,status));

            limitMsgs.push({entity_id:car.limitEntity,value:boostTarget,car:key,reason:'cheap_boost_start'});
            boostAuthorized=true; // Start immediately; do not wait for broker to reflect new limit.
            logMsgs.push(headerRow('cheap_boost_start',key,car,mode,s,reason));
        } else {
            // Important requirement: once rejected for this cheap window, do not reconsider
            // midway through the same window merely because the car later reaches normal target.
            suppressed=true;
            helperMsgs.push(setBoolMsg(`input_boolean.${key}_cheap_boost_suppressed`,true));
            helperMsgs.push(setDateTimeMsg(`input_datetime.${key}_cheap_boost_window_end_value`,priceWin.end));
            status='skipped_insufficient_window';
            reason=`Cheap window ends ${priceWin.end.toISOString()}; ${hoursToBoost.toFixed(2)}h required to reach ${boostTarget}% but only ${cheapHours.toFixed(2)}h available. Limit remains ${x.limit}%.`;
            helperMsgs.push(setTextMsg(`input_text.${key}_cheap_boost_status_value`,status));
            logMsgs.push(headerRow('cheap_boost_skip',key,car,mode,s,reason));
        }
    }

    // Existing active boost authorizes continuous charging for the WHOLE time price is below threshold.
    // It does not further optimize between sub-threshold prices.
    if (active && production && boostEnabled && eligible && priceWin.known && priceWin.cheap &&
        x.soc!==null && x.soc<boostTarget) {
        boostAuthorized=true;

        // If the broker still reports original limit immediately after activation, retry target 80.
        if (original!==null && x.limit!==null && approx(x.limit,original) && !approx(original,boostTarget)) {
            limitMsgs.push({entity_id:car.limitEntity,value:boostTarget,car:key,reason:'cheap_boost_target_retry'});
        }

        helperMsgs.push(setDateTimeMsg(`input_datetime.${key}_cheap_boost_window_end_value`,priceWin.end));
        helperMsgs.push(setTextMsg(`input_text.${key}_cheap_boost_status_value`,'active'));
    }

    boost[key]={
        active,suppressed,original,authorized:boostAuthorized,
        currentPrice:priceWin.price,cheap:priceWin.cheap,windowEnd:priceWin.end,
        availableKw:x.availableKw,status,reason
    };

    // --------------------------------------------------------
    // Normal planner + live target guard, aware of Cheap Boost.
    // --------------------------------------------------------
    // During active/just-activated boost, effective target is boostTarget.
    // This prevents live target guard from treating e.g. 70/70 as completed
    // before the temporary Tesla limit update is reflected by the broker.
    const effectiveTarget=boostAuthorized || active ? boostTarget : x.limit;
    const liveTargetReached=(x.soc!==null && effectiveTarget!==null && x.soc>=effectiveTarget);

    if (liveTargetReached && !(active && x.soc<boostTarget)) {
        helperMsgs.push(setBoolMsg(`input_boolean.${key}_optimizer_charge_authorized`,false));

        // Only invalidate the normal plan if no boost is still active.
        if (!active) {
            helperMsgs.push(setBoolMsg(`input_boolean.${key}_charge_plan_valid`,false));
            helperMsgs.push(setNumMsg(`input_number.${key}_charge_missing_kwh_value`,0));
            helperMsgs.push(setNumMsg(`input_number.${key}_charge_estimated_duration_value`,0));
            helperMsgs.push(setNumMsg(`input_number.${key}_charge_estimated_cost_value`,0));
            helperMsgs.push(setTextMsg(`input_text.${key}_charge_rule_value`,'target_reached'));
            helperMsgs.push(setTextMsg(`input_text.${key}_charge_optimizer_state_value`,'target_reached'));
            helperMsgs.push(setTextMsg(`input_text.${key}_charge_optimizer_reason_value`,
                `Live SoC ${x.soc}% has reached charge limit ${x.limit}%. Old plan invalidated immediately.`));
        }

        if (production && actual===true && eligible && !boostAuthorized) {
            offMsgs.push({entity_id:car.switchEntity,car:key});
            logMsgs.push(headerRow('target_reached_stop',key,car,mode,s,
                `Live SoC ${x.soc}% reached target ${effectiveTarget}%; stopping.`));
        }
        continue;
    }

    const normalEligible=!!s && !!s.controlEligible && x.cable;
    const normalNeedsCharge=!!s && s.soc!==null && s.target!==null && Number(s.soc)<Number(s.target);
    const normalActionable=!!s && (s.planValid || s.planActionable);
    const plannedNow=normalActionable && desiredNow(s,nowMs);
    const normalAuthorized=production && healthy && normalEligible && normalNeedsCharge && plannedNow;

    // A planned slot should never fail silently. If the slot is active but health blocks
    // normal authorization, record exactly why in CSV.
    if (production && normalEligible && normalNeedsCharge && plannedNow && !healthy && !boostAuthorized) {
        const activeSlot=s?.selectedSlots?.find(slot=>{
            const a=Date.parse(slot.start), b=Date.parse(slot.end);
            return Number.isFinite(a)&&Number.isFinite(b)&&nowMs>=a&&nowMs<b;
        });
        const blockId=`${activeSlot?.start||'unknown'}|health`;
        const ageMin=Number.isFinite(summaryAgeMs) ? (summaryAgeMs/60000).toFixed(1) : 'unknown';
        logBlockedOnce(
            key,car,s,
            `Scheduled charging slot is active but optimizer health is false. Plan age ${ageMin} min; maximum allowed age ${(maxSummaryAgeMs/60000).toFixed(0)} min.`,
            blockId
        );
    }

    const authorized=boostAuthorized || normalAuthorized;
    helperMsgs.push(setBoolMsg(`input_boolean.${key}_optimizer_charge_authorized`,authorized));

    // Clear previous blocked-start marker once the slot is authorized or no longer active.
    if (authorized || !plannedNow) {
        flow.set(`evopt_blocked_${key}`,null);
    }

    if (!production) continue;

    if (authorized) {
        if (actual!==true) {
            onMsgs.push({entity_id:car.switchEntity,car:key});
            logMsgs.push(headerRow(
                boostAuthorized?'cheap_boost_charge_start':'executor_start',
                key,car,mode,s,
                boostAuthorized
                    ? `Cheap Boost authorized: current price ${priceWin.price?.toFixed(4)} DKK/kWh is below ${boostThreshold.toFixed(2)}.`
                    : `Current time is inside a selected price slot; starting ${car.switchEntity}.`
            ));
        }
        continue;
    }

    // At known site, if healthy and neither normal plan nor boost authorizes charging, stop.
    if (healthy && normalEligible && actual===true) {
        offMsgs.push({entity_id:car.switchEntity,car:key});
        logMsgs.push(headerRow(watchdog?'watchdog_stop':'executor_stop',key,car,mode,s,
            watchdog
                ? 'Watchdog: charging is active but optimizer authorization is false.'
                : 'Neither normal price plan nor Cheap Boost authorizes charging now.'));
    }
}

// Debug payload
msg.payload={
    mode,production,healthy,watchdog,
    health:{
        summaryAgeMinutes:Number.isFinite(summaryAgeMs)?Number((summaryAgeMs/60000).toFixed(1)):null,
        maxSummaryAgeMinutes:maxSummaryAgeMs/60000
    },
    cheapBoost:{
        enabled:boostEnabled,
        thresholdDkkPerKwh:boostThreshold,
        targetPct:boostTarget,
        cars:boost
    },
    summaryAgeSeconds:Number.isFinite(summaryAgeMs)?Math.round(summaryAgeMs/1000):null,
    cars:Object.fromEntries(Object.keys(cars).map(key=>{
        const s=summaries[key];
        return [key,{
            controlSite:live[key]?.site||'none',
            connected:live[key]?.cable??null,
            liveSoc:live[key]?.soc??null,
            liveTarget:live[key]?.limit??null,
            planValid:s?.planValid??false,
            planActionable:s?.planActionable??false,
            plannedNow:s?desiredNow(s,nowMs):false,
            cheapBoostActive:boost[key]?.active??false,
            cheapBoostAuthorized:boost[key]?.authorized??false
        }];
    }))
};

return [helperMsgs,onMsgs,offMsgs,logMsgs,msg,limitMsgs];

// v0.5 actual charging energy/cost accumulator.
// Counts charging at known configured sites regardless of whether optimizer or native fallback started it.
// Uses Tesla-reported AC charging power as current fallback measurement.
// Later a site/charger meter can replace the power source without changing utility_meter history.

const ha = global.get('homeassistant');
const states =
    (ha && ha.homeAssistant && ha.homeAssistant.states) ||
    (ha && ha.states) || {};
const priceSources = flow.get('evopt_price_sources') || {};
const now = Date.now();

function st(e) {
    const x=states[e];
    if (!x) return null;
    const s=String(x.state??'').trim();
    if (!s || ['unknown','unavailable','none','null'].includes(s.toLowerCase())) return null;
    return s;
}
function num(e) {
    const s=st(e);
    if (s===null) return null;
    const n=Number(String(s).replace(',','.'));
    return Number.isFinite(n)?n:null;
}
function bool(e) {
    const s=st(e);
    if (s===null) return null;
    const v=s.toLowerCase();
    if (['on','true','yes','connected','charging'].includes(v)) return true;
    if (['off','false','no','disconnected','stopped','complete'].includes(v)) return false;
    return null;
}
function firstNum(a){ for(const e of a){const n=num(e); if(n!==null)return {value:n,entity:e};} return {value:null,entity:null};}
function firstBool(a){ for(const e of a){const b=bool(e); if(b!==null)return {value:b,entity:e};} return {value:null,entity:null};}
function firstState(a){ for(const e of a){const s=st(e); if(s!==null)return {value:s,entity:e};} return {value:null,entity:null};}
function locSite(v) {
    const l=String(v||'').trim().toLowerCase().replace(/_/g,' ').replace(/\s+/g,' ');
    if (l==='home') return 'anemonevej';
    if (['i.a. møllersvej','i.a møllersvej','i.a. mollersvej','i.a mollersvej'].includes(l)) return 'ia_moellersvej';
    return 'none';
}
function priceAt(source, ts) {
    const r=priceSources[source];
    if (!r || !Array.isArray(r.slots)) return null;
    for (const x of r.slots) {
        const a=Date.parse(x.start), b=Date.parse(x.end), p=Number(x.price);
        if (Number.isFinite(a)&&Number.isFinite(b)&&Number.isFinite(p)&&ts>=a&&ts<b) return p;
    }
    return null;
}
function safe(v,max=600){return String(v??'').replace(/[\r\n]+/g,' ').replace(/"/g,"'").slice(0,max);}
function setNum(entity_id,value){return {ha_action:'input_number.set_value',entity_id,value:Number(value)};}

const cars={
    blue_flux:{
        name:'Blue Flux',
        location:['sensor.blue_flux_broker_location','device_tracker.blue_flux_location'],
        connected:['binary_sensor.blue_flux_broker_charge_cable_connected','binary_sensor.blue_flux_charge_cable'],
        charging:['sensor.blue_flux_broker_charger_state','sensor.blue_flux_charging'],
        power:['sensor.blue_flux_broker_charger_power','sensor.blue_flux_charger_power'],
        energyTotal:'input_number.blue_flux_charge_actual_energy_total_value',
        costTotal:'input_number.blue_flux_charge_actual_cost_total_value'
    },
    ellingo:{
        name:'ElLingo',
        location:['sensor.ellingo_broker_location','device_tracker.ellingo_location'],
        connected:['binary_sensor.ellingo_broker_charge_cable_connected','binary_sensor.ellingo_charge_cable'],
        charging:['sensor.ellingo_broker_charger_state','sensor.ellingo_charging'],
        power:['sensor.ellingo_broker_charger_power','sensor.ellingo_charger_power_2'],
        energyTotal:'input_number.ellingo_charge_actual_energy_total_value',
        costTotal:'input_number.ellingo_charge_actual_cost_total_value'
    }
};

const actions=[], logs=[], debug={};

for (const [key,c] of Object.entries(cars)) {
    const location=firstState(c.location).value;
    const site=locSite(location);
    const connected=firstBool(c.connected).value===true;
    const powerPick=firstNum(c.power);
    let powerKw=powerPick.value;

    // Some integrations report W instead of kW. Normalize large values.
    if (powerKw!==null && powerKw>100) powerKw=powerKw/1000;

    const chargeState=firstState(c.charging).value;
    let charging=false;
    if (chargeState) {
        const v=String(chargeState).toLowerCase();
        charging=(v==='charging' || (v.includes('charg')&&!v.includes('not')&&!v.includes('dis')));
    }
    if (!charging && powerKw!==null && powerKw>0.05) charging=true;

    let priceSource='real_energy';
    if (site==='anemonevej') priceSource=st('input_text.ev_site_anemonevej_price_source')||'real_energy';
    if (site==='ia_moellersvej') priceSource=st('input_text.ev_site_ia_moellersvej_price_source')||'real_energy';
    const price=priceAt(priceSource,now);

    const ctxKey=`evopt_acc_${key}`;
    const prev=flow.get(ctxKey);
    flow.set(ctxKey,{ts:now,powerKw:powerKw??0});

    let dtHours=0;
    if (prev && Number.isFinite(prev.ts)) {
        const dtMs=now-prev.ts;
        // Ignore gaps > 3 minutes to avoid inventing energy after Node-RED/HA downtime.
        if (dtMs>0 && dtMs<=180000) dtHours=dtMs/3600000;
    }

    let addKwh=0, addCost=0, counted=false;
    if (site!=='none' && connected && charging && powerKw!==null && powerKw>0 && price!==null && dtHours>0) {
        // Trapezoid integration when previous power is available.
        const prevP=prev && Number.isFinite(prev.powerKw) ? Math.max(0,prev.powerKw) : powerKw;
        const avgP=(prevP+powerKw)/2;
        addKwh=avgP*dtHours;
        addCost=addKwh*price;

        const oldE=num(c.energyTotal)??0;
        const oldC=num(c.costTotal)??0;
        actions.push(setNum(c.energyTotal,Math.round((oldE+addKwh)*1000)/1000));
        actions.push(setNum(c.costTotal,Math.round((oldC+addCost)*1000)/1000));
        counted=true;
    }

    if (counted) {
        const row=[
            new Date(now).toISOString(),'actual_charge_cost_v1_1',key,c.name,'',
            '','',location||'',site,site,connected?'1':'0',chargeState||'',
            '','','','','',powerKw??'',priceSource,'', '', '', '', '',
            addCost.toFixed(4),price.toFixed(4),'',
            `${addKwh.toFixed(4)} kWh in ${(dtHours*60).toFixed(2)} min`,
            'actual_cost_accumulator',
            `Added ${addKwh.toFixed(4)} kWh / ${addCost.toFixed(4)} DKK using ${powerKw.toFixed(2)} kW @ ${price.toFixed(4)} DKK/kWh`,
            '','','',powerPick.entity||''
        ];
        logs.push({payload:row.map(v=>`"${safe(v)}"`).join(';')});
    }

    debug[key]={
        location,site,connected,charging,powerKw,
        priceSource,currentPrice:price,dtMinutes:dtHours*60,
        addedKwh:addKwh,addedCostDkk:addCost,counted
    };
}

msg.payload=debug;
return [actions,logs,msg];

// Coalesce broker-driven EV changes into one full optimizer calculation.
// Only broker presentation entities reach this node.
// Charge-limit and SoC changes therefore never depend on raw Fleet/Custom events.

const waitMs = 2000;

const oldTimer = context.get('timer');
if (oldTimer) clearTimeout(oldTimer);

const entity = msg.topic || msg.data?.entity_id || 'broker_change';
context.set('last_entity', String(entity));
context.set('last_payload', msg.payload);

const timer = setTimeout(() => {
    const trigger = context.get('last_entity') || 'broker_change';
    node.send({
        topic: trigger,
        trigger_source: 'broker_event',
        optimizer_recalc_reason: trigger,
        payload: {
            reason: 'broker_entity_changed',
            entity_id: trigger
        }
    });
    context.set('timer', null);
    node.status({fill:'green',shape:'dot',text:`replan: ${trigger}`});
}, waitMs);

context.set('timer', timer);
node.status({fill:'blue',shape:'dot',text:`waiting ${waitMs/1000}s: ${entity}`});
return null;

// EV Charge Optimizer v1.2 - odometer delta accumulator.
// First valid reading establishes a baseline and adds 0 km.
// Later increases are accumulated into a persistent lifetime "distance driven since v1.2 install" counter.
// Utility Meter in HA derives day/week/month/year from that monotonically increasing counter.

const ha=global.get('homeassistant');
const states=
    (ha && ha.homeAssistant && ha.homeAssistant.states) ||
    (ha && ha.states) || {};

function state(entity) {
    const x=states[entity];
    if (!x) return null;
    const s=String(x.state??'').trim();
    if (!s || ['unknown','unavailable','none','null'].includes(s.toLowerCase())) return null;
    return s;
}
function num(entity) {
    const s=state(entity);
    if (s===null) return null;
    const n=Number(String(s).replace(',','.'));
    return Number.isFinite(n)?n:null;
}
function bool(entity) {
    const s=state(entity);
    if (s===null) return null;
    return ['on','true','yes'].includes(s.toLowerCase());
}
function setNum(entity_id,value){return {ha_action:'input_number.set_value',entity_id,value:Number(value)};}
function setText(entity_id,value){return {ha_action:'input_text.set_value',entity_id,value:String(value).slice(0,255)};}
function setBool(entity_id,on){return {ha_action:on?'input_boolean.turn_on':'input_boolean.turn_off',entity_id};}
function safe(v,max=500){return String(v??'').replace(/[\r\n]+/g,' ').replace(/"/g,"'").slice(0,max);}
function normHay(s){return String(s||'').toLowerCase().replace(/[_-]+/g,' ');}

function normalizeKm(entity,value) {
    const unit=String(states[entity]?.attributes?.unit_of_measurement||'km').toLowerCase();
    if (unit==='mi' || unit==='mile' || unit==='miles') return value*1.609344;
    return value;
}

function discover(carKey,display,manual,explicit) {
    if (manual) {
        const n=num(manual);
        if (n!==null) return {entity:manual,valueKm:normalizeKm(manual,n),mode:'manual'};
    }

    for (const e of explicit) {
        const n=num(e);
        if (n!==null) return {entity:e,valueKm:normalizeKm(e,n),mode:'explicit'};
    }

    const carTokens=carKey==='blue_flux'
        ? ['blue flux','blueflux']
        : ['ellingo','el lingo','el_lingo'];

    const candidates=[];
    for (const [id,obj] of Object.entries(states)) {
        const friendly=String(obj?.attributes?.friendly_name||'');
        const hay=normHay(`${id} ${friendly}`);
        const isOdo=hay.includes('odometer') || hay.includes('mileage');
        const carMatch=carTokens.some(t=>hay.includes(normHay(t)));
        if (!isOdo || !carMatch) continue;
        const n=num(id);
        if (n===null) continue;

        let score=0;
        if (id.startsWith('sensor.')) score+=10;
        if (hay.includes('odometer')) score+=20;
        if (id.includes(carKey)) score+=30;
        if (friendly.toLowerCase().includes(display.toLowerCase())) score+=20;
        candidates.push({entity:id,valueKm:normalizeKm(id,n),mode:'auto',score});
    }

    candidates.sort((a,b)=>b.score-a.score);
    return candidates[0]||null;
}

const cars={
    blue_flux:{
        name:'Blue Flux',
        manual:'input_text.blue_flux_odometer_entity',
        source:'input_text.blue_flux_odometer_source_value',
        status:'input_text.blue_flux_odometer_status_value',
        init:'input_boolean.blue_flux_odometer_initialized',
        last:'input_number.blue_flux_odometer_last_value',
        total:'input_number.blue_flux_driven_distance_total_value',
        explicit:['sensor.blue_flux_odometer']
    },
    ellingo:{
        name:'ElLingo',
        manual:'input_text.ellingo_odometer_entity',
        source:'input_text.ellingo_odometer_source_value',
        status:'input_text.ellingo_odometer_status_value',
        init:'input_boolean.ellingo_odometer_initialized',
        last:'input_number.ellingo_odometer_last_value',
        total:'input_number.ellingo_driven_distance_total_value',
        explicit:['sensor.ellingo_odometer','sensor.ellingo_odometer_2']
    }
};

const actions=[],logs=[],debug={};

for (const [key,c] of Object.entries(cars)) {
    const manual=state(c.manual);
    const found=discover(key,c.name,manual,c.explicit);

    if (!found) {
        actions.push(setText(c.status,'odometer_not_found'));
        actions.push(setText(c.source,'none'));
        debug[key]={status:'odometer_not_found',manual:manual||null};
        continue;
    }

    const current=Math.round(found.valueKm*100)/100;
    const oldSource=state(c.source);
    const initialized=bool(c.init)===true;
    const last=num(c.last);
    const oldTotal=num(c.total)??0;

    // New source or first read: establish baseline only.
    if (!initialized || !last || oldSource!==found.entity) {
        actions.push(setNum(c.last,current));
        actions.push(setText(c.source,found.entity));
        actions.push(setText(c.status,`baseline ${current.toFixed(2)} km via ${found.entity}`));
        actions.push(setBool(c.init,true));
        debug[key]={status:'baseline',source:found.entity,odometerKm:current,totalKm:oldTotal};
        continue;
    }

    let delta=current-last;

    // Odometer should never go backwards. If it does, rebase safely without adding km.
    if (delta < -0.01) {
        actions.push(setNum(c.last,current));
        actions.push(setText(c.status,`odometer decreased ${last.toFixed(2)}→${current.toFixed(2)} km; rebased, no distance added`));
        logs.push({payload:[
            new Date().toISOString(),'odometer_rebase_v1_2',key,c.name,'','','','','','','','','','','','','','','','','','','','','','','','',
            'odometer_rebase',
            `Odometer decreased from ${last.toFixed(2)} to ${current.toFixed(2)} km; no distance counted.`,
            found.entity,'','',''
        ].map(v=>`"${safe(v)}"`).join(';')});
        debug[key]={status:'rebase',source:found.entity,odometerKm:current,lastKm:last};
        continue;
    }

    // Protect against unit/source glitches.
    if (delta > 5000) {
        actions.push(setText(c.status,`odometer jump ${delta.toFixed(2)} km rejected`));
        debug[key]={status:'outlier_rejected',source:found.entity,odometerKm:current,lastKm:last,deltaKm:delta};
        continue;
    }

    if (delta >= 0.01) {
        const newTotal=Math.round((oldTotal+delta)*100)/100;
        actions.push(setNum(c.total,newTotal));
        actions.push(setNum(c.last,current));
        actions.push(setText(c.source,found.entity));
        actions.push(setText(c.status,`ok +${delta.toFixed(2)} km; odometer ${current.toFixed(2)} km`));

        logs.push({payload:[
            new Date().toISOString(),'odometer_delta_v1_2',key,c.name,'','','','','','','','','','','','','','','','','','','','','','','','',
            'odometer_delta',
            `Added ${delta.toFixed(2)} km from ${found.entity}; odometer ${current.toFixed(2)} km; cumulative tracked ${newTotal.toFixed(2)} km.`,
            found.entity,'','',''
        ].map(v=>`"${safe(v)}"`).join(';')});

        debug[key]={status:'ok',source:found.entity,odometerKm:current,deltaKm:delta,totalKm:newTotal};
    } else {
        actions.push(setText(c.source,found.entity));
        actions.push(setText(c.status,`ok; odometer ${current.toFixed(2)} km`));
        debug[key]={status:'unchanged',source:found.entity,odometerKm:current,totalKm:oldTotal};
    }
}

msg.payload=debug;
return [actions,logs,msg];
